changeSet.sql:
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='1min';
LOCK TABLE kabipay_ops.integration_connector IN ACCESS EXCLUSIVE MODE;
CREATE FUNCTION kabipay_ops.preserve_integration_connector_identity()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $identity$
BEGIN
 IF TG_OP IN ('DELETE','TRUNCATE') THEN
  RAISE EXCEPTION 'Integration catalog identities must be retained; set is_active=false instead';
 END IF;
 IF NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'Integration connector identity is immutable';END IF;
 RETURN NEW;
END $identity$;
CREATE TRIGGER trg_integration_connector_keep_id BEFORE UPDATE OF id ON kabipay_ops.integration_connector
 FOR EACH ROW EXECUTE FUNCTION kabipay_ops.preserve_integration_connector_identity();
CREATE TRIGGER trg_integration_connector_keep_rows BEFORE DELETE ON kabipay_ops.integration_connector
 FOR EACH ROW EXECUTE FUNCTION kabipay_ops.preserve_integration_connector_identity();
CREATE TRIGGER trg_integration_connector_keep_truncate BEFORE TRUNCATE ON kabipay_ops.integration_connector
 FOR EACH STATEMENT EXECUTE FUNCTION kabipay_ops.preserve_integration_connector_identity();
ALTER TABLE kabipay_ops.integration_connector ENABLE ALWAYS TRIGGER trg_integration_connector_keep_id;
ALTER TABLE kabipay_ops.integration_connector ENABLE ALWAYS TRIGGER trg_integration_connector_keep_rows;
ALTER TABLE kabipay_ops.integration_connector ENABLE ALWAYS TRIGGER trg_integration_connector_keep_truncate;
